function renderDivergencias(){const f=filtrados();const itens=f.flatMap(r=>detalheDivergencias(r).map(v=>({...v,reg:r})));$('view-divergencias').innerHTML=cabecalho('Divergências atuais · Google Sheets × SMS Rio','Cada linha mostra o valor existente em cada fonte')+'<div class="panel"><div class="panel-body"><div class="table-wrap"><table><thead><tr><th>Competência</th><th>Categoria</th><th>Sigla</th><th class="left">Indicador</th><th class="left">Grupo</th><th>Google Sheets</th><th>SMS Rio</th></tr></thead><tbody>'+(itens.map(x=>'<tr><td>'+esc(x.reg.competencia)+'</td><td>'+esc(x.reg.categoria)+'</td><td>'+esc(x.reg.sigla)+'</td><td class="left"><b>'+esc(reparar(x.campo))+'</b></td><td class="left">'+esc(reparar(x.grupo))+'</td><td>'+formatar(x.campo,x.planilha)+'</td><td class="diff">'+formatar(x.campo,x.smsRio)+'</td></tr>').join('')||'<tr><td colspan="7" class="empty">Nenhuma divergência neste recorte.</td></tr>')+'</tbody></table></div></div></div>'}
function unidadeSelecionada(){return catalogo.find(x=>x.id===state.unidade)}
function registrosUnidade(){return D.filter(x=>(!state.ano||x.ano===Number(state.ano))&&(!state.mes||x.mes===Number(state.mes))&&chave(x.categoria,x.sigla)===state.unidade).sort((a,b)=>a.mes-b.mes)}
function formatarDelta(campo,delta){if(delta===null||!Number.isFinite(delta))return '—';const sinal=delta>0?'+':delta<0?'−':'';const abs=Math.abs(delta),tipo=tipoUnidade(campo),n=abs.toLocaleString('pt-BR',{minimumFractionDigits:tipo==='numero'&&abs>=100?0:2,maximumFractionDigits:2});return sinal+n+(tipo==='percentual'?' p.p.':tipo==='permil'?'‰':'')}
function variacaoFonte(regs,campo,fonte,ms){const atualMes=state.mes?Number(state.mes):ms.at(-1),anteriores=ms.filter(m=>m<atualMes),anteriorMes=anteriores.at(-1);if(!atualMes||!anteriorMes)return {html:'<td class="variation-cell var-flat">—</td><td class="variation-cell var-flat">—</td>',rotulo:''};const atualReg=regs.find(x=>Number(x.mes)===atualMes),antReg=D.find(x=>x.ano===Number(atualReg?.ano||state.ano)&&Number(x.mes)===anteriorMes&&chave(x.categoria,x.sigla)===state.unidade);const atualRaw=dadosValores(atualReg).find(v=>v.campo===campo)?.[fonte],antRaw=dadosValores(antReg).find(v=>v.campo===campo)?.[fonte];if(!preenchido(atualRaw)||!preenchido(antRaw))return {html:'<td class="variation-cell var-flat">—</td><td class="variation-cell var-flat">—</td>',rotulo:(meses[atualMes]||'')+' × '+(meses[anteriorMes]||'')};const atual=valorVisual(campo,atualRaw),ant=valorVisual(campo,antRaw);if(atual===null||ant===null)return {html:'<td class="variation-cell var-flat">—</td><td class="variation-cell var-flat">—</td>',rotulo:''};const delta=atual-ant,pct=Math.abs(ant)>1e-12?delta/Math.abs(ant)*100:null,cls=Math.abs(delta)<1e-10?'var-flat':delta>0?'var-up':'var-down',seta=Math.abs(delta)<1e-10?'→':delta>0?'▲':'▼',pctTxt=pct===null?'—':(pct>0?'+':'')+pct.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%';return {html:'<td class="variation-cell '+cls+'">'+seta+' '+formatarDelta(campo,delta)+'</td><td class="variation-cell '+cls+'">'+seta+' '+pctTxt+'</td>',rotulo:(meses[atualMes]||'')+' × '+(meses[anteriorMes]||'')}}
function tabelaUnidade(tipo){const u=unidadeSelecionada(),regs=registrosUnidade();if(!u)return '<p class="empty">Selecione uma unidade no filtro superior.</p>';if(!regs.length)return '<p class="empty">A unidade está configurada, mas ainda não possui fotografia concluída neste recorte. Ela continuará disponível para acompanhamento.</p>';const {ano,ms}=mesesRecorte();if(!ms.length)return '<p class="empty">Não há competências com dados disponíveis para este ano.</p>';const campos=valoresOrdenados(regs);if(!campos.length)return '<p class="empty">A unidade está configurada, porém não há indicadores coletados nesta competência.</p>';const compara=tipo==='compare';const fonte=tipo==='sms'?'smsRio':'planilha';const variacao=!compara;const atualMes=state.mes?Number(state.mes):ms.at(-1),anteriorMes=ms.filter(m=>m<atualMes).at(-1),rotVar=anteriorMes?((meses[atualMes]||'')+'/'+ano+' × '+(meses[anteriorMes]||'')+'/'+ano):'Atual × anterior';const h1='<tr><th rowspan="2" class="sticky-col">Indicador</th>'+ms.map(m=>'<th colspan="'+(compara?3:1)+'" class="month-head">'+meses[m]+'/'+ano+'</th>').join('')+(variacao?'<th rowspan="2" class="variation-head">Variação<br><small>'+esc(rotVar)+'</small></th><th rowspan="2" class="variation-head">Variação relativa<br><small>(%)</small></th>':'')+'</tr>';const h2='<tr>'+ms.map(()=>compara?'<th class="subhead">Google Sheets</th><th class="subhead">SMS Rio</th><th class="subhead month-end">Situação</th>':'<th class="subhead month-end">Valor</th>').join('')+'</tr>';let ultimoGrupo='',body='';campos.forEach(c=>{if(c.grupo!==ultimoGrupo){ultimoGrupo=c.grupo;body+='<tr class="group-row"><td colspan="'+(1+ms.length*(compara?3:1)+(variacao?2:0))+'">'+esc(reparar(c.grupo||'Sem grupo'))+'</td></tr>'}let linha='<tr><td class="sticky-col"><b>'+esc(reparar(c.campo))+'</b></td>'+ms.map(m=>{const r=regs.find(x=>x.mes===m),v=dadosValores(r).find(x=>x.campo===c.campo);if(!v)return compara?'<td>—</td><td>—</td><td class="month-end neutral">Não verificado</td>':'<td class="month-end">—</td>';if(!compara)return '<td class="month-end">'+formatar(c.campo,v[fonte])+'</td>';if(!r?.possuiDados&&!preenchido(v.smsRio)){const rotulo=r?.status==='MES_NAO_DISPONIVEL_SMSRIO'?'Sem competência no SMS':'SMS não verificado';return '<td>'+formatar(c.campo,v.planilha)+'</td><td>—</td><td class="month-end pending">'+rotulo+'</td>'}return '<td>'+formatar(c.campo,v.planilha)+'</td><td><b>'+formatar(c.campo,v.smsRio)+'</b></td><td class="month-end '+(igual(v.planilha,v.smsRio)?'same':'diff')+'">'+(igual(v.planilha,v.smsRio)?'OK':'Diferente')+'</td>'}).join('');if(variacao)linha+=variacaoFonte(regs,c.campo,fonte,ms).html;body+=linha+'</tr>'});const nota=variacao&&anteriorMes?'<div class="variation-note"><span>↗</span><span><b>Variação mensal:</b> compara '+esc(meses[atualMes]+'/'+ano)+' com '+esc(meses[anteriorMes]+'/'+ano)+'. As cores indicam somente a direção da mudança, não classificam o resultado como bom ou ruim.</span></div>':'';return '<div class="table-wrap"><table><thead>'+h1+h2+'</thead><tbody>'+body+'</tbody></table></div>'+nota}
function renderComparativoUnidade(){const u=unidadeSelecionada();$('view-comparativo-unidade').innerHTML=cabecalho('Comparativo por unidade',u?u.sigla+' — '+esc(u.unidade):'Selecione uma unidade para ver todos os indicadores na ordem do Macro')+'<div class="panel"><div class="panel-body"><div class="note">Os indicadores respeitam a ordem das linhas do relatório mensal do Macro: grupo e indicador, sem ordenação alfabética.</div>'+tabelaUnidade('compare')+'</div></div>'}
function indicadoresDisponiveisComparativo(){return valoresOrdenados(D.filter(r=>(!state.categoria||r.categoria===state.categoria)&&registroTemConteudo(r))).map(x=>x.campo)}
let compareState={indicador:'',fonte:'smsRio',inicioA:'',fimA:'',inicioB:'',fimB:''};
function compsComparativo(){return uniq(D.filter(r=>(!state.categoria||r.categoria===state.categoria)&&registroTemConteudo(r)).map(r=>r.competencia).filter(Boolean)).sort()}
function compMaisProxima(comps,alvo,anoPreferido=null){if(!comps.length)return '';if(comps.includes(alvo))return alvo;const base=anoPreferido?comps.filter(c=>Number(c.slice(0,4))===Number(anoPreferido)):comps;if(!base.length)return comps.at(-1);const n=Number(String(alvo||'').replace('-',''))||Number(base.at(-1).replace('-',''));return base.reduce((a,b)=>Math.abs(Number(a.replace('-',''))-n)<=Math.abs(Number(b.replace('-',''))-n)?a:b)}
function anoAnterior(comp,comps){if(!comp)return '';const a=Number(comp.slice(0,4))-1,m=comp.slice(5,7),alvo=String(a)+'-'+m;return compMaisProxima(comps,alvo,a)}
function padraoComparativo(comps){if(!comps.length)return;const disponiveisAno=state.ano?comps.filter(c=>Number(c.slice(0,4))===Number(state.ano)&&(!state.mes||Number(c.slice(5,7))<=Number(state.mes))):comps;const atual=disponiveisAno.at(-1)||comps.at(-1),anterior=anoAnterior(atual,comps)||comps[0];const valido=x=>comps.includes(x);if(!valido(compareState.inicioA))compareState.inicioA=atual;if(!valido(compareState.fimA))compareState.fimA=atual;if(!valido(compareState.inicioB))compareState.inicioB=anterior;if(!valido(compareState.fimB))compareState.fimB=anterior;if(compareState.inicioA>compareState.fimA)[compareState.inicioA,compareState.fimA]=[compareState.fimA,compareState.inicioA];if(compareState.inicioB>compareState.fimB)[compareState.inicioB,compareState.fimB]=[compareState.fimB,compareState.inicioB]}
function copiarPeriodoAnoAnterior(comps){if(!compareState.inicioA||!compareState.fimA)return;compareState.inicioB=anoAnterior(compareState.inicioA,comps);compareState.fimB=anoAnterior(compareState.fimA,comps);if(compareState.inicioB>compareState.fimB)[compareState.inicioB,compareState.fimB]=[compareState.fimB,compareState.inicioB]}
