function mediaNumerica(vals){const v=vals.filter(x=>x!==null&&Number.isFinite(x));return v.length?v.reduce((a,b)=>a+b,0)/v.length:null}
function resumoValores(campo,vals){const v=vals.filter(x=>x!==null&&Number.isFinite(x));if(!v.length)return '—';const med=v.reduce((a,b)=>a+b,0)/v.length,tipo=tipoUnidade(campo);if(tipo==='numero'){const total=v.reduce((a,b)=>a+b,0);return 'Total '+formatarEixo(campo,total)+' · Média '+formatarEixo(campo,med)}return 'Média '+formatarEixo(campo,med)}
